INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Kommunikation > Kommunikations-Modelle > Watzlawicks 5 Axiome
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Besagt das erste Axiom von Watzlawick, dass man nicht nicht kommunizieren kann?', 2, '[{"text": "Ja", "correct": true, "because": "Jede Form von Verhalten ist Kommunikation"}, {"text": "Nein", "correct": false, "because": "Das ist die zentrale Aussage des ersten Axioms"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann laut Watzlawicks zweitem Axiom eine Kommunikation nur aus Inhaltsaspekten bestehen?', 2, '[{"text": "Nein", "correct": true, "because": "Jede Kommunikation hat Inhalts- und Beziehungsaspekte"}, {"text": "Ja", "correct": false, "because": "Das zweite Axiom betont beide Ebenen"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es nach dem dritten Axiom möglich, dass Kommunikation ohne Ursache-Wirkung interpretiert wird?', 2, '[{"text": "Nein", "correct": true, "because": "Kommunikation wird als wechselseitiger Prozess gesehen"}, {"text": "Ja", "correct": false, "because": "Das dritte Axiom beschreibt Kausalität"}]'),
('00000000-0000-0000-0000-000000000000', 'Können nonverbale Signale laut Watzlawicks viertem Axiom die Kommunikation dominieren?', 2, '[{"text": "Ja", "correct": true, "because": "Verbale und nonverbale Kommunikation interagieren"}, {"text": "Nein", "correct": false, "because": "Nonverbale Signale sind oft maßgeblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Besagt das fünfte Axiom, dass alle Kommunikation entweder symmetrisch oder komplementär ist?', 2, '[{"text": "Ja", "correct": true, "because": "Es beschreibt Gleichheit oder Unterschiedlichkeit"}, {"text": "Nein", "correct": false, "because": "Das ist die Definition des fünften Axioms"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Axiom von Watzlawick beschreibt, dass Schweigen auch eine Form der Kommunikation ist?', 3, '[{"text": "Erstes Axiom", "correct": true, "because": "Man kann nicht nicht kommunizieren"}, {"text": "Drittes Axiom", "correct": false, "because": "Bezieht sich auf Ursache-Wirkung"}, {"text": "Fünftes Axiom", "correct": false, "because": "Bezieht sich auf Symmetrie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Axiom betont die Bedeutung der Beziehungsebene in der Kommunikation?', 2, '[{"text": "Zweites Axiom", "correct": true, "because": "Inhalt und Beziehung beeinflussen sich"}, {"text": "Viertes Axiom", "correct": false, "because": "Fokussiert verbale/nonverbale Mittel"}, {"text": "Erstes Axiom", "correct": false, "because": "Fokussiert allgemeine Kommunikation"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel von Watzlawicks drittem Axiom?', 2, '[{"text": "Kommunikation als wechselseitigen Prozess darstellen", "correct": true, "because": "Ursache und Wirkung sind zirkulär"}, {"text": "Technische Details erklären", "correct": false, "because": "Nicht das Ziel"}, {"text": "Symmetrie definieren", "correct": false, "because": "Fünftes Axiom"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Axiom beschreibt die Rolle von verbalen und nonverbalen Elementen?', 3, '[{"text": "Viertes Axiom", "correct": true, "because": "Unterscheidet Kommunikationsmittel"}, {"text": "Zweites Axiom", "correct": false, "because": "Fokussiert Inhalt/Beziehung"}, {"text": "Drittes Axiom", "correct": false, "because": "Fokussiert Kausalität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Axiom unterscheidet zwischen gleichrangiger und hierarchischer Kommunikation?', 2, '[{"text": "Fünftes Axiom", "correct": true, "because": "Symmetrisch vs. komplementär"}, {"text": "Erstes Axiom", "correct": false, "because": "Allgemeine Kommunikation"}, {"text": "Zweites Axiom", "correct": false, "because": "Inhalt/Beziehung"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Axiome betonen die Vielschichtigkeit der Kommunikation?', 4, '[{"text": "Erstes Axiom", "correct": true, "because": "Alles ist Kommunikation"}, {"text": "Zweites Axiom", "correct": true, "because": "Inhalt und Beziehung"}, {"text": "Viertes Axiom", "correct": true, "because": "Verbale/nonverbale Mittel"}, {"text": "Drittes Axiom", "correct": false, "because": "Fokussiert Kausalität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen gehören zu Watzlawicks Axiomen?', 3, '[{"text": "Man kann nicht nicht kommunizieren", "correct": true, "because": "Erstes Axiom"}, {"text": "Kommunikation hat Inhalts- und Beziehungsaspekte", "correct": true, "because": "Zweites Axiom"}, {"text": "Kommunikation ist symmetrisch oder komplementär", "correct": true, "because": "Fünftes Axiom"}, {"text": "Kommunikation ist immer technisch", "correct": false, "because": "Nicht Teil der Axiome"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte beeinflussen laut Watzlawicks Axiomen die Kommunikation?', 4, '[{"text": "Nonverbale Signale", "correct": true, "because": "Viertes Axiom"}, {"text": "Beziehungsebene", "correct": true, "because": "Zweites Axiom"}, {"text": "Wechselwirkung", "correct": true, "because": "Drittes Axiom"}, {"text": "Hardwareleistung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können durch Missachtung der Axiome entstehen?', 3, '[{"text": "Missverständnisse", "correct": true, "because": "Zweites Axiom ignoriert"}, {"text": "Konflikte durch Machtgefälle", "correct": true, "because": "Fünftes Axiom übersehen"}, {"text": "Fehlinterpretation von Signalen", "correct": true, "because": "Viertes Axiom missachtet"}, {"text": "Schnellere Lösungen", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente der Kommunikation werden durch Watzlawicks Axiome beschrieben?', 3, '[{"text": "Verhalten als Kommunikation", "correct": true, "because": "Erstes Axiom"}, {"text": "Ursache-Wirkung", "correct": true, "because": "Drittes Axiom"}, {"text": "Symmetrie/Komplementarität", "correct": true, "because": "Fünftes Axiom"}, {"text": "Technische Protokolle", "correct": false, "because": "Nicht Teil der Axiome"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das erste Axiom besagt, dass Schweigen Kommunikation ist. b) Das zweite Axiom ignoriert die Beziehungsebene.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schweigen ja, Beziehung zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das dritte Axiom beschreibt Kommunikation als zirkulär. b) Das vierte Axiom fokussiert nur verbale Mittel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zirkulär ja, verbal/nonverbal nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das fünfte Axiom unterscheidet symmetrische Kommunikation. b) Watzlawicks Axiome gelten nur für technische Systeme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Symmetrie ja, allgemein anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Das zweite Axiom betont die Beziehungsebene. b) Das dritte Axiom ignoriert Wechselwirkungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Beziehung ja, Wechselwirkung zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das vierte Axiom beschreibt nonverbale Kommunikation. b) Das erste Axiom ist nur auf Worte beschränkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nonverbal ja, Verhalten allgemein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

